        previous_sma = sum(spy_closes[:-1]) / 100.0
        current_sma = sum(spy_closes[1:]) / 100.0
        previous_spy_close = spy_closes[-2]
        current_spy_close = spy_closes[-1]

        spy_crossed_above_sma = (
            previous_spy_close <= previous_sma
            and current_spy_close > current_sma
        )
        spy_crossed_below_sma = (
            previous_spy_close >= previous_sma
            and current_spy_close < current_sma
        )

        aapl_close = present["AAPL"].Close

        # Sells are evaluated before buys.
        if self.strategy_a_lot > 0 and spy_crossed_below_sma:
            self.MarketOrder(self.symbols["SPY"], -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and self.aapl_rsi > 60:
            self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_lot)
            self.strategy_b_lot = 0

