            quantity = math.floor(
                (self.Portfolio.TotalPortfolioValue * 0.40) / current_spy_close
            )
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.strategy_a_lot = quantity

        if self.strategy_b_lot == 0 and self.red_streak["AAPL"] >= 3:
            if self.Portfolio.Cash >= 20_000:
                quantity = math.floor(20_000 / aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.strategy_b_lot = quantity

    def UpdateAaplRsi(self, close):
        if self.rsi_previous_close is None:
            self.rsi_previous_close = close
            return

        change = close - self.rsi_previous_close
        gain = max(change, 0.0)
        loss = max(-change, 0.0)
        self.rsi_previous_close = close
        self.rsi_changes += 1

        if self.rsi_changes <= 14:
            self.rsi_seed_gains += gain
            self.rsi_seed_losses += loss

            if self.rsi_changes == 14:
                self.rsi_average_gain = self.rsi_seed_gains / 14.0
                self.rsi_average_loss = self.rsi_seed_losses / 14.0
                self.aapl_rsi = self.CalculateRsi()
            return

        self.rsi_average_gain = (
            (self.rsi_average_gain * 13.0) + gain
        ) / 14.0
        self.rsi_average_loss = (
            (self.rsi_average_loss * 13.0) + loss
        ) / 14.0
        self.aapl_rsi = self.CalculateRsi()

    def CalculateRsi(self):
        if self.rsi_average_loss == 0:
            return 100.0

        relative_strength = self.rsi_average_gain / self.rsi_average_loss
        return 100.0 - (100.0 / (1.0 + relative_strength))
